import{getBFCacheRestoreTime}from"../lib/bfcache.js";import{getLoadState}from"../lib/getLoadState.js";import{getNavigationEntry}from"../lib/getNavigationEntry.js";import{onFCP as unattributedOnFCP}from"../onFCP.js";const attributeFCP=t=>{let e={timeToFirstByte:0,firstByteToFCP:t.value,loadState:getLoadState(getBFCacheRestoreTime())};if(t.entries.length){const a=getNavigationEntry(),i=t.entries.at(-1);if(a){const o=a.activationStart||0,r=Math.max(0,a.responseStart-o);e={timeToFirstByte:r,firstByteToFCP:t.value-r,loadState:getLoadState(t.entries[0].startTime),navigationEntry:a,fcpEntry:i}}}return Object.assign(t,{attribution:e})};export const onFCP=(t,e={})=>{unattributedOnFCP(e=>{t(attributeFCP(e))},e)};